module rearrange_to_divisible_by_7 (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] input_digits [0:15],\n    input wire [3:0] input_length,\n    output reg [3:0] output_digits [0:15],\n    output reg done\n);\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COUNT = 3'd1;\n    localparam [2:0] DECREMENT = 3'd2;\n    localparam [2:0] CALCULATE_MOD = 3'd3;\n    localparam [2:0] LOOKUP = 3'd4;\n    localparam [2:0] OUTPUT = 3'd5;\n    \n    reg [2:0] state, next_state;\n    reg [4:0] count [0:9];\n    reg [2:0] mod_result;\n    reg [3:0] digit_counter;\n    reg [3:0] output_index;\n    reg [15:0] current_perm;\n    reg [7:0] cycle_counter;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Permutation table\n    reg [15:0] perm_table [0:6];\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize state machine\n            state <= IDLE;\n            done <= 1'b0;\n            mod_result <= 3'd0;\n            digit_counter <= 4'd0;\n            output_index <= 4'd0;\n            current_perm <= 16'd0;\n            cycle_counter <= 8'd0;\n            \n            // Initialize count array\n            for (integer i = 0; i < 10; i = i + 1) begin\n                count[i] <= 5'd0;\n            end\n            \n            // Initialize output array\n            for (integer i = 0; i < 16; i = i + 1) begin\n                output_digits[i] <= 4'd0;\n            end\n            \n            // Initialize permutation table\n            perm_table[0] <= 16'h1869;\n            perm_table[1] <= 16'h1896;\n            perm_table[2] <= 16'h1986;\n            perm_table[3] <= 16'h1698;\n            perm_table[4] <= 16'h6198;\n            perm_table[5] <= 16'h1689;\n            perm_table[6] <= 16'h1968;\n        end else begin\n            state <= next_state;\n            cycle_counter <= (state != next_state) ? 8'd0 : cycle_counter + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Reset counters\n                        for (integer i = 0; i < 10; i = i + 1) begin\n                            count[i] <= 5'd0;\n                        end\n                        digit_counter <= 4'd0;\n                    end\n                end\n                \n                COUNT: begin\n                    if (digit_counter < input_length) begin\n                        count[input_digits[digit_counter]] <= count[input_digits[digit_counter]] + 5'd1;\n                        digit_counter <= digit_counter + 4'd1;\n                    end\n                end\n                \n                DECREMENT: begin\n                    // Decrement special digits (1,6,8,9)\n                    if (count[4'd1] > 0) count[4'd1] <= count[4'd1] - 5'd1;\n                    if (count[4'd6] > 0) count[4'd6] <= count[4'd6] - 5'd1;\n                    if (count[4'd8] > 0) count[4'd8] <= count[4'd8] - 5'd1;\n                    if (count[4'd9] > 0) count[4'd9] <= count[4'd9] - 5'd1;\n                    digit_counter <= 4'd0;\n                end\n                \n                CALCULATE_MOD: begin\n                    if (digit_counter < 4'd10) begin\n                        if (count[digit_counter] > 0) begin\n                            mod_result <= ((mod_result * 4'd10) + digit_counter) % 3'd7;\n                            count[digit_counter] <= count[digit_counter] - 5'd1;\n                        end else begin\n                            digit_counter <= digit_counter + 4'd1;\n                        end\n                    end\n                end\n                \n                LOOKUP: begin\n                    current_perm <= perm_table[mod_result];\n                    output_index <= 4'd0;\n                    digit_counter <= 4'd9;  // Start from highest digit\n                end\n                \n                OUTPUT: begin\n                    // Main digits (9 to 1, skip 0)\n                    if (digit_counter > 4'd0 && output_index < (input_length - 4'd4)) begin\n                        if (count[digit_counter] > 0) begin\n                            output_digits[output_index] <= digit_counter;\n                            output_index <= output_index + 4'd1;\n                            count[digit_counter] <= count[digit_counter] - 5'd1;\n                        end else begin\n                            digit_counter <= digit_counter - 4'd1;\n                        end\n                    end\n                    // Insert permutation\n                    else if (output_index < (input_length - 4'd4)) begin\n                        output_digits[output_index] <= current_perm[15:12];\n                        output_digits[output_index+1] <= current_perm[11:8];\n                        output_digits[output_index+2] <= current_perm[7:4];\n                        output_digits[output_index+3] <= current_perm[3:0];\n                        output_index <= output_index + 4'd4;\n                        digit_counter <= 4'd0;  // Process zeros next\n                    end\n                    // Zeros\n                    else if (digit_counter == 4'd0 && output_index < input_length) begin\n                        if (count[0] > 0) begin\n                            output_digits[output_index] <= 4'd0;\n                            output_index <= output_index + 4'd1;\n                            count[0] <= count[0] - 5'd1;\n                        end else begin\n                            done <= 1'b1;\n                        end\n                    end else begin\n                        done <= 1'b1;\n                    end\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n            \n            // Timeout protection\n            if (cycle_counter >= MAX_CYCLES) begin\n                state <= IDLE;\n                done <= 1'b1;\n            end\n        end\n    end\n    \n    always @(*) begin\n        case (state)\n            IDLE: next_state = (start) ? COUNT : IDLE;\n            COUNT: next_state = (digit_counter >= input_length) ? DECREMENT : COUNT;\n            DECREMENT: next_state = CALCULATE_MOD;\n            CALCULATE_MOD: next_state = (digit_counter >= 4'd10) ? LOOKUP : CALCULATE_MOD;\n            LOOKUP: next_state = OUTPUT;\n            OUTPUT: next_state = (done) ? IDLE : OUTPUT;\n            default: next_state = IDLE;\n        endcase\n    end\nendmodule